// Some portions generated by Co-Pilot
import { fireEvent, render, screen } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { axe } from "vitest-axe";
import VendorSelector from "../index";
import vendors from "@/data/marketplace.json";
import getVendorIdentifier from "@/utils/vendors";

vi.mock("next-intl", () => ({
  useTranslations:
    () => (key: string, values?: { selected: number; total: number }) =>
      key === "vendors-selected" && values
        ? `${values.selected} of ${values.total} vendors selected`
        : key,
}));

const selected = vendors.map(getVendorIdentifier);
const onChange = vi.fn();

describe("Marketplace vendor selection", () => {
  beforeEach(() => vi.clearAllMocks());

  it("shows each vendor once with its selection state", () => {
    render(
      <VendorSelector
        selectedVendorIdentifiers={selected}
        setSelectedVendorIdentifiers={onChange}
      />,
    );
    expect(screen.getAllByRole("button")).toHaveLength(vendors.length);
    expect(
      screen.getByText(
        `${vendors.length} of ${vendors.length} vendors selected`,
      ),
    ).toBeInTheDocument();
    for (const vendor of vendors)
      expect(screen.getByRole("button", { name: vendor.name })).toHaveAttribute(
        "aria-pressed",
        "true",
      );
  });

  it("does not overwrite parent selections while mounting", () => {
    render(
      <VendorSelector
        selectedVendorIdentifiers={[]}
        setSelectedVendorIdentifiers={onChange}
      />,
    );
    expect(onChange).not.toHaveBeenCalled();
    expect(
      screen.getByText(`0 of ${vendors.length} vendors selected`),
    ).toBeVisible();
  });

  it("removes a selected vendor exactly once", () => {
    render(
      <VendorSelector
        selectedVendorIdentifiers={selected}
        setSelectedVendorIdentifiers={onChange}
      />,
    );
    fireEvent.click(screen.getByRole("button", { name: vendors[0].name }));
    expect(onChange).toHaveBeenCalledExactlyOnceWith(selected.slice(1));
  });

  it("adds an unselected vendor without changing the others", () => {
    render(
      <VendorSelector
        selectedVendorIdentifiers={selected.slice(1)}
        setSelectedVendorIdentifiers={onChange}
      />,
    );
    const button = screen.getByRole("button", { name: vendors[0].name });
    expect(button).toHaveAttribute("aria-pressed", "false");
    fireEvent.click(button);
    expect(onChange).toHaveBeenCalledExactlyOnceWith([
      ...selected.slice(1),
      selected[0],
    ]);
  });

  it("has no accessibility violations", async () => {
    const { container } = render(
      <VendorSelector
        selectedVendorIdentifiers={selected}
        setSelectedVendorIdentifiers={onChange}
      />,
    );
    expect(await axe(container)).toHaveNoViolations();
  });
});
